import * as openpgp from 'openpgp';

// Генерация ключей
export const generateKeys = async () => {
  const { privateKey, publicKey } = await openpgp.generateKey({
    userIDs: [{ name: 'Anonymous' }],
    curve: 'ed25519',
  });
  return { privateKey, publicKey };
};

// Шифрование сообщения
export const encryptMessage = async (message, publicKey) => {
  const encrypted = await openpgp.encrypt({
    message: await openpgp.createMessage({ text: message }),
    encryptionKeys: await openpgp.readKey({ armoredKey: publicKey }),
  });
  return encrypted;
};

// Расшифровка сообщения
export const decryptMessage = async (encryptedMessage, privateKey) => {
  const decrypted = await openpgp.decrypt({
    message: await openpgp.readMessage({ armoredMessage: encryptedMessage }),
    decryptionKeys: await openpgp.readPrivateKey({ armoredKey: privateKey }),
  });
  return decrypted.data;
};

// Хранение приватного ключа
export const storePrivateKey = async (privateKey) => {
  const db = await window.indexedDB.open('chatKeysDB', 1);
  db.onupgradeneeded = (event) => {
    const db = event.target.result;
    db.createObjectStore('keys', { keyPath: 'id' });
  };
  const transaction = db.result.transaction(['keys'], 'readwrite');
  transaction.objectStore('keys').add({ id: 'privateKey', key: privateKey });
};

// Извлечение приватного ключа
export const retrievePrivateKey = async () => {
  const db = await window.indexedDB.open('chatKeysDB', 1);
  const transaction = db.result.transaction(['keys'], 'readonly');
  const store = transaction.objectStore('keys');
  return store.get('privateKey').key;
};
